import{_ as a,a as t,o,a4 as l}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"Locales","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/locales/index.md","filePath":"api/rest-api/shop/locales/index.md","lastUpdated":1784902076000}'),s={name:"api/rest-api/shop/locales/index.md"};function i(n,e,r,d,c,h){return o(),t("div",null,e[0]||(e[0]=[l('<h1 id="locales" tabindex="-1">Locales <a class="header-anchor" href="#locales" aria-label="Permalink to &quot;Locales&quot;">​</a></h1><p>The Locales menu lists the languages the storefront is published in. A locale carries its language code, display name, text direction (<code>ltr</code> / <code>rtl</code>) and an optional logo. Use it to build a language switcher, to know which <code>locale</code> codes you may pass on catalog and content requests, and to render right-to-left layouts correctly.</p><h2 id="when-a-client-uses-this" tabindex="-1">When a client uses this <a class="header-anchor" href="#when-a-client-uses-this" aria-label="Permalink to &quot;When a client uses this&quot;">​</a></h2><p>Call the list endpoint once on app start to populate a language picker, then fetch a single locale by id when you need its full detail. The <code>code</code> you read here is the same value you send as the <code>locale</code> query parameter on product, category and other localised requests.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/locales/get-locales.html">Get All Locales</a></td><td><code>GET /api/shop/locales</code></td><td>Paginated list of every available locale.</td></tr><tr><td><a href="/api/rest-api/shop/locales/get-single-locale.html">Get Single Locale</a></td><td><code>GET /api/shop/locales/{id}</code></td><td>A single locale by id.</td></tr></tbody></table><p>All Locale endpoints are public reads that require only the storefront key — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',7)]))}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
